export function ContainerComponent({
  dataLabel = "{{dataLabel}}",
  value = "{{value}}",
  state = "{{state}}",
  accent = "{{accent}}",
}) {
  const loading = state === "loading";
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 280, boxSizing: "border-box", textAlign: "center" }}>
      <div style={{ border: `2px dashed ${accent}`, borderRadius: 8, padding: 10, fontWeight: 700 }}>
        UserContainer
        <small style={{ display: "block", fontWeight: 400, fontSize: 10, color: "#24143099", marginTop: 4 }}>fetches {dataLabel}</small>
      </div>
      <span aria-hidden="true" style={{ display: "block", fontSize: 16, color: "#24143060", margin: "4px 0" }}>&darr;</span>
      <div style={{ border: "1.5px solid #24143020", borderRadius: 8, padding: 10, fontWeight: 700, marginTop: 4 }}>
        UserView (presentational)
        {loading
          ? <div role="status" aria-label="loading" style={{ height: 16, borderRadius: 4, background: "#24143014", margin: "8px auto 0", width: "70%" }} />
          : <div style={{ marginTop: 8, fontWeight: 600 }}>{value}</div>}
      </div>
    </div>
  );
}
